import{_ as a,o as i,c as t,a3 as n}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.6 Automatic Maximum Gross Production","description":"","frontmatter":{"translationSource":{"title":"1.6智能最大毛产","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}]]},"headers":[],"relativePath":"full-storage-oscillation-plan.md","filePath":"logistics/src/page-JEibHxjUhjwaznRy5jp6oc.md"}'),o={name:"full-storage-oscillation-plan.md"};function r(s,e,l,p,d,c){return i(),t("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><h1 id="_1-6-automatic-maximum-gross-production" tabindex="-1">1.6 Automatic Maximum Gross Production <a class="header-anchor" href="#_1-6-automatic-maximum-gross-production" aria-label="Permalink to &quot;1.6 Automatic Maximum Gross Production&quot;">​</a></h1><blockquote><p>Source page ID: <code>JEibHxjUhjwaznRy5jp6oc</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-red"><strong>#言: Where&#39;s my Xiranite module?</strong></span></p><p>Requirements:</p><p>Jingyu Valley: 12 Xiranite units with two Depot Loader inputs each. The self-starting plan with 12 such units and 9 Control Ports is ready. Cursed-engineering point: the facility count has exploded.</p><p>Other sections:</p><p>Yinglung Pass: remove Xiranite oversupply, place the automatically connected conduits outside, and add things (Separator Cores).</p><p>The main base needs compression (Refining Units, Sewage-treatment trash can, Xircon line, Ferrium refining/shredding and Separator Cores, half-rate batteries/, Xiranite oscillation/, Xiranite fluid-gas transmutation/, Xiranite bus/, Heavy Xiranite/).</p><p><span id="source-block-wt8iPy0gMDFywV7KEmhkoR"></span></p><h2 id="video-script" tabindex="-1">Video Script <a class="header-anchor" href="#video-script" aria-label="Permalink to &quot;Video Script&quot;">​</a></h2><p><span id="source-block-YS3tBMxxg8McQAfMF35GpN"></span></p><h3 id="production-line-showcase" tabindex="-1">Production Line Showcase <a class="header-anchor" href="#production-line-showcase" aria-label="Permalink to &quot;Production Line Showcase&quot;">​</a></h3><p>How this generation surpasses the previous one</p><p>A more detailed feature introduction, especially a demonstration of the add-ons</p><p>Expectations for the audience: to leave positive comments in the comment section, for example; to bring most questions to the Q&amp;A site and the group chats, and to make clear that we lack the capacity to answer each one individually; and, on noticing that the comment section and even group members contain many incorrect replies, to affirm the helpful spirit first, then point out that wrong replies cause confusion, and finally not to condemn anyone outright but to further suggest that anyone with questions go to the group or the Q&amp;A site and treat the Q&amp;A staff&#39;s answers as authoritative—the staff may not be absolutely correct, but it is undeniable that they are more familiar with the production line than most people and can pass questions on to the developers at any time.</p><p><span id="source-block-UU4P5kkrLs4f54xy23COub"></span></p><h3 id="production-line-explanation" tabindex="-1">Production Line Explanation <a class="header-anchor" href="#production-line-explanation" aria-label="Permalink to &quot;Production Line Explanation&quot;">​</a></h3><p>Module overview</p><p>Explanation of the automatic-balancing path</p><p><span id="source-block-VjRatZPY7VytfwEPSU53Zl"></span></p><h3 id="installation-tutorial" tabindex="-1">Installation Tutorial <a class="header-anchor" href="#installation-tutorial" aria-label="Permalink to &quot;Installation Tutorial&quot;">​</a></h3><p><span id="source-block-0rfOwq29K0j4iJLxK2zROW"></span></p><h2 id="production-line-layout" tabindex="-1">Production Line Layout <a class="header-anchor" href="#production-line-layout" aria-label="Permalink to &quot;Production Line Layout&quot;">​</a></h2><p><span id="source-block-pZevVPXGlCFmWxYpA22zV7"></span></p><h3 id="jingyu-valley" tabindex="-1">Jingyu Valley <a class="header-anchor" href="#jingyu-valley" aria-label="Permalink to &quot;Jingyu Valley&quot;">​</a></h3><p><strong>Current main constraint: the facility count</strong></p><p>12 Xiranite units with two Depot Loader inputs each (required)</p><p>2 Separator Cores (required)</p><p>3 Cuprium refining setups with two belts each (required)</p><p>Planting group: one belt each of Yazhen and Jincao, plus shredding (required)</p><p>Ferrium refining with overflow to shredding</p><p>Fitting Units: 3 Pyrrolite, 1 Hetonite, 1 Ferrium</p><p>Pyrrolite Component Gearing Unit</p><p>SC Wuling Batteries (optional) (can be Sandleaf or Packaging)</p><p><span id="source-block-tkw1iLW0nUBPYwoeRyJccp"></span></p><h3 id="main-base" tabindex="-1">Main Base <a class="header-anchor" href="#main-base" aria-label="Permalink to &quot;Main Base&quot;">​</a></h3><p>Liquid Xiranite oscillation (4 crucibles</p><p>2 fixed crucibles, compatible</p><p>All-Condition Xircon</p><p>Cuprium refining with overflow to shredding: 12</p><p>Cuprium refining with two belts, 2 coupled trash cans</p><p>Basic medicine line starting from Ferrium and Ferrium Parts</p><p>SC Wuling Batteries</p><p><span id="source-block-krXKbnL5O0kAIMgiAR5mXr"></span></p><h3 id="yinglung-pass" tabindex="-1">Yinglung Pass <a class="header-anchor" href="#yinglung-pass" aria-label="Permalink to &quot;Yinglung Pass&quot;">​</a></h3><p>Conduits placed outside — Solid-Gas Transmuting Units switched to overflow, plus Separator Cores</p><p><span id="source-block-wtaH6muc44xSRMXmWrcqDs"></span></p><h3 id="marker-stone" tabindex="-1">Marker Stone <a class="header-anchor" href="#marker-stone" aria-label="Permalink to &quot;Marker Stone&quot;">​</a></h3><p><span id="source-block-6SkebfDdeH1om407PRb3Pg"></span></p><h5 id="daily-necessities-add-on" tabindex="-1">Daily Necessities Add-On <a class="header-anchor" href="#daily-necessities-add-on" aria-label="Permalink to &quot;Daily Necessities Add-On&quot;">​</a></h5><p><span id="source-block-0kspTcZc9FCeTSNB1Zsg97"></span></p><h5 id="紫药-tentative-purple-tier-medicine-canned-liquid-xiranite-canned-heavy-liquid-xiranite-cuprium-parts-小电-tentative-low-capacity-battery-to-be-added" tabindex="-1">紫药 (tentative: purple-tier medicine), Canned Liquid Xiranite, Canned Heavy Liquid Xiranite, Cuprium Parts, 小电 (tentative: low-capacity battery), To Be Added <a class="header-anchor" href="#紫药-tentative-purple-tier-medicine-canned-liquid-xiranite-canned-heavy-liquid-xiranite-cuprium-parts-小电-tentative-low-capacity-battery-to-be-added" aria-label="Permalink to &quot;紫药 (tentative: purple-tier medicine), Canned Liquid Xiranite, Canned Heavy Liquid Xiranite, Cuprium Parts, 小电 (tentative: low-capacity battery), To Be Added&quot;">​</a></h5><p><span id="source-block-5Fcbr8mwQYsbQVWw3qnHU8"></span></p><h5 id="yuanyuan-manor-add-on" tabindex="-1">Yuanyuan Manor Add-On <a class="header-anchor" href="#yuanyuan-manor-add-on" aria-label="Permalink to &quot;Yuanyuan Manor Add-On&quot;">​</a></h5><p><span id="source-block-FBtPNvsLFil3Wtwnz99gI5"></span></p><h2 id="standalone-modules" tabindex="-1">Standalone Modules <a class="header-anchor" href="#standalone-modules" aria-label="Permalink to &quot;Standalone Modules&quot;">​</a></h2><p><span id="source-block-Z5vNKLZ8EC4EtG1KTC6C8F"></span></p><h3 id="xircon-line" tabindex="-1">Xircon Line <a class="header-anchor" href="#xircon-line" aria-label="Permalink to &quot;Xircon Line&quot;">​</a></h3><p>Arknights: Endfield blueprint [Single-Sided All-Condition Xircon], share code EF01u28U5Ie870a7AoOU. Copy it and use it in the game.</p><p><span id="source-block-HUOTrAo1XGkxDqwoWUNxYD"></span></p><h3 id="heavy-xiranite" tabindex="-1">Heavy Xiranite <a class="header-anchor" href="#heavy-xiranite" aria-label="Permalink to &quot;Heavy Xiranite&quot;">​</a></h3><p>Arknights: Endfield blueprint [Four-Core Heavy Xiranite], share code EF01I43EaUUUu9o45o08. Copy it and use it in the game.</p><p><span id="source-block-A8b2BmNv3r8OczTH6mi4LB"></span></p><h3 id="copper-processing" tabindex="-1">Copper Processing <a class="header-anchor" href="#copper-processing" aria-label="Permalink to &quot;Copper Processing&quot;">​</a></h3><p>Arknights: Endfield blueprint [Temporary Refining], share code EF013Eo56eee8a510579. Copy it and use it in the game.<br> Arknights: Endfield blueprint [Separator Core], share code EF01U9ea48887OiI7Oa8. Copy it and use it in the game.</p><p><span id="source-block-h3O6ZElo5DYvpwQqWExr9k"></span></p><h3 id="ferrium-processing" tabindex="-1">Ferrium Processing <a class="header-anchor" href="#ferrium-processing" aria-label="Permalink to &quot;Ferrium Processing&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abd42c7b4bee2263.q90-fcf8ba08a760fb80.webp" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="K6uojhba5PhZY4h7JS1DHr"><p>赫塔 — Ferrium refining and shredding</p></div><p><span id="source-block-V6Z6WWObS8Sp9VROKaVcgK"></span></p><h3 id="xiranite" tabindex="-1">Xiranite <a class="header-anchor" href="#xiranite" aria-label="Permalink to &quot;Xiranite&quot;">​</a></h3><p><span class="mark-red">Where is it? Hurry up and bring it out!!!</span></p><p><span id="source-block-PSVH9EWPl3In6oiZbgmPV9"></span></p><h3 id="liquid-xiranite-full-storage-oscillation-module" tabindex="-1">Liquid Xiranite Full-Storage Oscillation Module <a class="header-anchor" href="#liquid-xiranite-full-storage-oscillation-module" aria-label="Permalink to &quot;Liquid Xiranite Full-Storage Oscillation Module&quot;">​</a></h3><p><span id="source-block-qFVfEvK9jO1NhKefnV1XSG"></span></p><h4 id="controlling-xiranite" tabindex="-1">Controlling Xiranite <a class="header-anchor" href="#controlling-xiranite" aria-label="Permalink to &quot;Controlling Xiranite&quot;">​</a></h4><p><span id="source-block-GiL6uZNnTppYmPRchrcBmr"></span></p><h4 id="controlling-water" tabindex="-1">Controlling Water <a class="header-anchor" href="#controlling-water" aria-label="Permalink to &quot;Controlling Water&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7c56052227e27422.q90-4b211e99002b0a11.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>Filler: put 250 Jincao in every box except the unpowered one at the far left. Fill the unpowered tank with 4 miscellaneous items, and use enough Jincao Seeds to fill the length of the belt.</p><p>This should save a great many facilities, at the cost of only 4 pipe components. I have not compressed it yet, though ((</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-280aed2b84bcdf55.png" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="cXD5Oa5klddFZoIT9qBbsU"><p>The priorities are as shown in the figure.</p></div><p>Initial compression is complete. Preparing the unpowered tank takes quite a while; I do not know whether to optimize that.</p><p><s>Arknights: Endfield blueprint [Wuling Unpowered Tank], share code EF015i2eii8O2uaa0eIoe. Copy it and use it in the game.</s></p><p><s>Arknights: Endfield blueprint [Oscillating Liquid Xiranite], share code EF01E75U77u25o56E3uIa. Copy it and use it in the game.</s></p><p><strong>Already optimized by 君大人</strong></p></div>',1)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
